// The configuration for compute nodes in a pool based on the Azure Virtual Machines infrastructure.
type VirtualMachineConfiguration_STATUS struct {
	// ContainerConfiguration: If specified, setup is performed on each node in the pool to allow tasks to run in containers.
	// All regular tasks and job manager tasks run on this pool must specify the containerSettings property, and all other
	// tasks may specify it.
	ContainerConfiguration *ContainerConfiguration_STATUS `json:"containerConfiguration,omitempty"`

	// DataDisks: This property must be specified if the compute nodes in the pool need to have empty data disks attached to
	// them.
	DataDisks []DataDisk_STATUS `json:"dataDisks,omitempty"`

	// DiskEncryptionConfiguration: If specified, encryption is performed on each node in the pool during node provisioning.
	DiskEncryptionConfiguration *DiskEncryptionConfiguration_STATUS `json:"diskEncryptionConfiguration,omitempty"`

	// Extensions: If specified, the extensions mentioned in this configuration will be installed on each node.
	Extensions []VMExtension_STATUS `json:"extensions,omitempty"`

	// ImageReference: A reference to an Azure Virtual Machines Marketplace image or the Azure Image resource of a custom
	// Virtual Machine. To get the list of all imageReferences verified by Azure Batch, see the 'List supported node agent
	// SKUs' operation.
	ImageReference *ImageReference_STATUS `json:"imageReference,omitempty"`

	// LicenseType: This only applies to images that contain the Windows operating system, and should only be used when you
	// hold valid on-premises licenses for the nodes which will be deployed. If omitted, no on-premises licensing discount is
	// applied. Values are:
	// Windows_Server - The on-premises license is for Windows Server.
	// Windows_Client - The on-premises license is for Windows Client.
	LicenseType *string `json:"licenseType,omitempty"`

	// NodeAgentSkuId: The Batch node agent is a program that runs on each node in the pool, and provides the
	// command-and-control interface between the node and the Batch service. There are different implementations of the node
	// agent, known as SKUs, for different operating systems. You must specify a node agent SKU which matches the selected
	// image reference. To get the list of supported node agent SKUs along with their list of verified image references, see
	// the 'List supported node agent SKUs' operation.
	NodeAgentSkuId *string `json:"nodeAgentSkuId,omitempty"`

	// NodePlacementConfiguration: This configuration will specify rules on how nodes in the pool will be physically allocated.
	NodePlacementConfiguration *NodePlacementConfiguration_STATUS `json:"nodePlacementConfiguration,omitempty"`

	// OsDisk: Contains configuration for ephemeral OSDisk settings.
	OsDisk *OSDisk_STATUS `json:"osDisk,omitempty"`

	// SecurityProfile: Specifies the security profile settings for the virtual machine or virtual machine scale set.
	SecurityProfile *SecurityProfile_STATUS `json:"securityProfile,omitempty"`

	// ServiceArtifactReference: The service artifact reference id in the form of
	// /subscriptions/{subscriptionId}/resourceGroups/{resourceGroup}/providers/Microsoft.Compute/galleries/{galleryName}/serviceArtifacts/{serviceArtifactName}/vmArtifactsProfiles/{vmArtifactsProfilesName}
	ServiceArtifactReference *ServiceArtifactReference_STATUS `json:"serviceArtifactReference,omitempty"`

	// WindowsConfiguration: This property must not be specified if the imageReference specifies a Linux OS image.
	WindowsConfiguration *WindowsConfiguration_STATUS `json:"windowsConfiguration,omitempty"`
}

